  {
    "tab": "File",
    "visible": true,
    "groups": [
      {
        "group": "Document",
        "buttons": [
          {
            "label": "Home",
            "enabled": true,
            "checked": false,
            "description": "The home screen: your workspace folder, recent parts, new part."
          },
          {
            "label": "New",
            "enabled": true,
            "checked": false,
            "description": "Start an empty document."
          },
          {
            "label": "Open",
            "enabled": true,
            "checked": false,
            "description": "Open an OurCAD or STEP file."
          },
          {
            "label": "Save",
            "enabled": true,
            "checked": false,
            "description": "Save the document."
          },
          {
            "label": "Save As",
            "enabled": true,
            "checked": false,
            "description": "Save under a new name."
          }
        ]
      },
      {
        "group": "Exchange",
        "buttons": [
          {
            "label": "Import STEP",
            "enabled": true,
            "checked": false,
            "description": "Bring a STEP (.step/.stp) model into the document."
          },
          {
            "label": "Export STEP",
            "enabled": true,
            "checked": false,
            "description": "Write all visible objects as a STEP file."
          },
          {
            "label": "Import Mesh",
            "enabled": true,
            "checked": false,
            "description": "Bring in a scan or print file: STL, OBJ, PLY or 3MF."
          },
          {
            "label": "Export 3MF",
            "enabled": true,
            "checked": false,
            "description": "Write a 3MF file for printing: keeps each body separate, in millimetres. Exports the selection, or everything if nothing is selected."
          },
          {
            "label": "Export STL",
            "enabled": true,
            "checked": false,
            "description": "Write a triangle mesh (STL). Exports the selection, or everything if nothing is selected."
          },
          {
            "label": "Export OBJ",
            "enabled": true,
            "checked": false,
            "description": "Write a Wavefront OBJ mesh."
          },
          {
            "label": "Export PLY",
            "enabled": true,
            "checked": false,
            "description": "Write a PLY mesh."
          }
        ]
      }
    ]
  },
  {
    "tab": "Home",
    "visible": true,
    "groups": [
      {
        "group": "Sketch",
        "buttons": [
          {
            "label": "Create Sketch",
            "enabled": true,
            "checked": false,
            "description": "Draw 2D profiles on a plane or a face. Profiles drive extrudes, revolves, sweeps and lofts."
