          {
            "label": "Edit Sketch",
            "enabled": false,
            "checked": false,
            "description": "Re-open the selected sketch: its geometry, constraints and dimensions are all still editable."
          },
          {
            "label": "3D Sketch",
            "enabled": true,
            "checked": false,
            "description": "Draw lines, splines, arcs, circles and rectangles in space. The drawing plane follows your last point, Tab turns it, Shift lifts a point out of the plane, and Move points edits them later. Makes curves for sweeps and lofts."
          }
        ]
      },
      {
        "group": "Planes",
        "buttons": [
          {
            "label": "Construction Plane",
            "enabled": true,
            "checked": false,
            "description": "Make planes: offset (one or a whole stack), angled, midway, square to a curve, or through three points. Sketch on them or use them as references."
          },
          {
            "label": "Intersection Curve",
            "enabled": true,
            "checked": false,
            "description": "The curve where two planes, faces or bodies cross each other."
          },
          {
            "label": "Look At",
            "enabled": true,
            "checked": false,
            "description": "Turn the view to look straight at the selected plane, face or sketch (or the sketch you are drawing)."
          }
        ]
      },
      {
        "group": "Create",
        "buttons": [
          {
            "label": "Box",
            "enabled": true,
            "checked": false,
            "description": "Create a box, cylinder, sphere, cone or torus. Click the icon to make the one shown; click the name (or right-click) to pick another."
