        ]
      },
      {
        "group": "Features",
        "buttons": [
          {
            "label": "Extrude",
            "enabled": true,
            "checked": false,
            "description": "Push a sketch profile or face into a solid."
          },
          {
            "label": "Revolve",
            "enabled": true,
            "checked": false,
            "description": "Spin a profile around an axis."
          },
          {
            "label": "Edit Feature",
            "enabled": false,
            "checked": false,
            "description": "Go back into a feature you made (Extrude, Revolve, Fillet, Shell...) and change its numbers or picks. The model rolls back to just before it; OK puts it back and rebuilds the steps that came after. You can also right-click a step in the History."
          }
        ]
      },
      {
        "group": "Modify",
        "buttons": [
          {
            "label": "Fillet",
            "enabled": true,
            "checked": false,
            "description": "Round off selected edges."
          },
          {
            "label": "Chamfer",
            "enabled": true,
            "checked": false,
            "description": "Bevel selected edges."
          }
        ]
      },
      {
        "group": "Combine",
