          {
            "label": "Union",
            "enabled": true,
            "checked": false,
            "description": "Merge bodies into one."
          },
          {
            "label": "Subtract",
            "enabled": true,
            "checked": false,
            "description": "Cut one body out of another."
          },
          {
            "label": "Intersect",
            "enabled": true,
            "checked": false,
            "description": "Keep only the shared volume."
          }
        ]
      },
      {
        "group": "Transform",
