            "checked": false,
            "description": "Translate objects."
          },
          {
            "label": "Rotate",
            "enabled": true,
            "checked": false,
            "description": "Rotate objects around an axis."
          },
          {
            "label": "Scale",
            "enabled": true,
            "checked": false,
            "description": "Resize objects uniformly."
          },
          {
            "label": "Mirror",
            "enabled": true,
            "checked": false,
            "description": "Reflect objects across a plane."
          },
          {
            "label": "Duplicate",
            "enabled": false,
            "checked": false,
            "description": "Copy the selected objects."
          },
          {
            "label": "Delete",
            "enabled": false,
            "checked": false,
            "description": "Remove the selected objects."
          }
        ]
      },
      {
        "group": "Appearance",
        "buttons": [
          {
            "label": "Materials",
            "enabled": true,
            "checked": false,
            "description": "Open the material library: engineering data for steels, aluminum, plastics and more, with colors and finishes you can apply to bodies."
          }
        ]
      },
      {
        "group": "Image",
        "buttons": [
          {
            "label": "Import Image",
            "enabled": true,
            "checked": false,
