          },
          {
            "label": "Edit Image",
            "enabled": true,
            "checked": false,
            "description": "Change a picture\u0027s opacity, size, position, turn or mirroring."
          },
          {
            "label": "Set Scale",
            "enabled": true,
            "checked": false,
            "description": "Make a picture true size: click two points on it and say how far apart they really are."
